      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-cutout-pet\",\n  \"version\": \"1.0.0\",\n  \"description\": \"Turn any picture into a floating desk pet in the Harness Web UI: local background removal, sticker outline, idle animation and a live account-balance bubble.\",\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"desktop-pet\",\n    \"cutout\",\n    \"background-removal\",\n    \"sticker\",\n    \"balance\"\n  ],\n  \"license\": \"MIT\",\n  \"author\": \"AlannerFranklin\",\n  \"homepage\": \"https://github.com/AlannerFranklin/dsh-cutout-pet\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/AlannerFranklin/dsh-cutout-pet.git\"\n  },\n  \"icon\": \"icon.svg\",\n  \"type\": \"module\",\n  \"engines\": {\n    \"node\": \">=20\"\n  },\n  \"exports\": {\n    \".\": \"./index.js\",\n    \"./client\": \"./client.js\",\n    \"./locale/*.json\": \"./locale/*.json\",\n    \"./icon\": \"./icon.svg\"\n  },\n  \"files\": [\n    \"index.js\",\n    \"client.js\",\n    \"cordis.patch.yml\",\n    \"locale/*.json\",\n    \"icon.svg\",\n    \"assets/default.png\",\n    \"README.md\",\n    \"LICENSE\"\n  ],\n  \"dsh\": {\n    \"bundle\": { \"patch\": \"./cordis.patch.yml\" },\n    \"client\": {\n      \"platform\": \"web\",\n      \"immediately\": true,\n      \"inject\": []\n    }\n  }\n}\n"
